import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement returns customer statement with issued invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(inv1, []).value;

  const r = statement('C-001', [issued], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(r.value.invoices[0].issueDate, '2026-10-07');
  assert.equal(r.value.invoices[0].total, 20570);
  assert.equal(r.value.invoices[0].due, 20570);
  assert.equal(r.value.totalDue, 20570);
});

test('statement filters invoices before asOf date', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const r = statement('C-001', [issued1, issued2], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
});

test('statement includes invoices on asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const r = statement('C-001', [issued], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
});

test('statement excludes invoices after asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-11',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const r = statement('C-001', [issued], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
  assert.equal(r.value.totalDue, 0);
});

test('statement excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = statement('C-001', [inv], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
});

test('statement includes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total: 10285
  const paid = recordPayment(issued, { amount: 10285, date: '2026-10-08' }).value;

  const r = statement('C-001', [paid], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].due, 0);
  assert.equal(r.value.totalDue, 0);
});

test('statement filters by customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const r = statement('C-001', [issued1, issued2], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
});

test('statement reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = statement('C-999', [], '2026-10-10');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement sorts invoices by issueDate', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
