    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  const r = statement('C-001', [issued1, issued2, issued3], '2026-10-20');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 3);
  assert.equal(r.value.invoices[0].issueDate, '2026-10-05');
  assert.equal(r.value.invoices[1].issueDate, '2026-10-10');
  assert.equal(r.value.invoices[2].issueDate, '2026-10-15');
});

test('statement calculates totalDue as sum of individual due amounts', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  // Invoice 1: 10285
  // Invoice 2: 20570
  // Total: 30855
