test('statement empty for customer with no invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const r = statement('C-001', [issued], '2026-10-10');
