});

test('statement with large number of invoices', () => {
  const invoices = [];
  for (let i = 1; i <= 10; i++) {
    const inv = createInvoice({
      customerId: 'C-001',
      issueDate: `2026-10-${String(i).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: i }],
    }).value;

    const issued = issueInvoice(inv, invoices.map(ii => ii.number)).value;
    invoices.push(issued);
  }

  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 10);

  // Verify they're sorted by issueDate
  for (let i = 1; i < r.value.invoices.length; i++) {
    assert.ok(
      r.value.invoices[i - 1].issueDate <= r.value.invoices[i].issueDate,
      `Invoice ${i} out of order`
    );
  }
});

