    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // C-001 gold tier: Total = 19542
  const p1 = recordPayment(issued, { amount: 5000, date: '2026-10-08' }).value;
  const p2 = recordPayment(p1, { amount: 8000, date: '2026-10-09' }).value;

  const r = statement('C-001', [p2], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].due, 6542);
  assert.equal(r.value.totalDue, 6542);
});

