test('statement with mix of statuses', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued2 = issueInvoice(inv2, []).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001']).value;
  // C-001 gold tier: DES-HOUR (1) = 8500 - 425 (5%) + 1696 (21%) = 9771
  const paid3 = recordPayment(issued3, { amount: 9771, date: '2026-10-11' }).value;

  const r = statement('C-001', [draft, issued2, paid3], '2026-10-15');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(r.value.invoices[0].due, 9771);
  assert.equal(r.value.invoices[1].number, 'INV-2026-0002');
  assert.equal(r.value.invoices[1].due, 0);
  assert.equal(r.value.totalDue, 9771);
});

