test('statement handles year boundaries', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-25',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const r = statement('C-001', [issued1, issued2], '2026-01-01');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].issueDate, '2025-12-25');
});

test('statement with invoices with vouchers', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // C-001 gold tier: Total without voucher = 19542

  // Manually add voucher (simulating applyVoucher on issued invoice)
  const withVoucher = {
    ...issued,
    voucher: { code: 'WELCOME', amount: 2000 },
  };

  const r = statement('C-001', [withVoucher], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  // Total: 19542 - 2000 = 17542
  assert.equal(r.value.invoices[0].total, 17542);
  assert.equal(r.value.invoices[0].due, 17542);
  assert.equal(r.value.totalDue, 17542);
});

test('statement with invoices with discounts', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // DES-HOUR: 17000, discount: 1700, amount after discount: 15300, VAT: 3213, Total: 18513

  const r = statement('C-001', [issued], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].total, 18513);
  assert.equal(r.value.invoices[0].due, 18513);
});

test('statement returns proper structure', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const r = statement('C-001', [issued], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(typeof r.value.customerId, 'string');
  assert.ok(Array.isArray(r.value.invoices));
  assert.equal(typeof r.value.totalDue, 'number');

  if (r.value.invoices.length > 0) {
    const inv = r.value.invoices[0];
    assert.ok(inv.number);
    assert.ok(inv.issueDate);
    assert.ok(inv.dueDate);
    assert.equal(typeof inv.total, 'number');
    assert.equal(typeof inv.due, 'number');
  }
});

test('statement with large number of invoices', () => {
  const invoices = [];
  for (let i = 1; i <= 10; i++) {
    const inv = createInvoice({
      customerId: 'C-001',
      issueDate: `2026-10-${String(i).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: i }],
    }).value;

    const issued = issueInvoice(inv, invoices.map(ii => ii.number)).value;
    invoices.push(issued);
  }

  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 10);

  // Verify they're sorted by issueDate
  for (let i = 1; i < r.value.invoices.length; i++) {
    assert.ok(
      r.value.invoices[i - 1].issueDate <= r.value.invoices[i].issueDate,
      `Invoice ${i} out of order`
    );
  }
});

test('statement normalizes customer ID', () => {
  const inv = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  // Request statement with different case
  const r = statement('C-001', [issued], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
});

test('statement with early date excludes all invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const r = statement('C-001', [issued], '2026-10-09');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
  assert.equal(r.value.totalDue, 0);
});

